INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7560510, 1212173, 30861, '<td valign="top">Got that green flash! So rare! :-)</td>', 'Got that green flash! So rare! :-)', '2018-02-23 00:16:56.000000', NULL, 1),
(7560526, 1212180, 56502, '<td valign="top">Too good to be bad :-) - nice laugh!</td>', 'Too good to be bad :-) - nice laugh!', '2018-02-23 02:55:03.000000', NULL, 1),
(7560551, 1212156, 140305, '<td valign="top">I''d say you nailed it lol.</td>', 'I''d say you nailed it lol.', '2018-02-23 12:02:15.000000', NULL, 1),
(7560552, 1212166, 140305, '<td valign="top">Nicely done! I think I see a front page finish in your future...</td>', 'Nicely done! I think I see a front page finish in your future...', '2018-02-23 12:04:00.000000', NULL, 1),
(7560553, 1212150, 140305, '<td valign="top">I like your interpretation of the challenge i.e., bad weather = great photo. Very nicely done, great composition &amp; love the muted colours.</td>', 'I like your interpretation of the challenge i.e., bad weather = great photo. Very nicely done, great composition & love the muted colours.', '2018-02-23 12:10:13.000000', NULL, 1),
(7560554, 1212179, 140305, '<td valign="top">I really like this, the effect is quite jarring. Nicely done.</td>', 'I really like this, the effect is quite jarring. Nicely done.', '2018-02-23 12:17:44.000000', NULL, 1),
(7560555, 1212180, 140305, '<td valign="top">How can you not smile at this? Love it.</td>', 'How can you not smile at this? Love it.', '2018-02-23 12:18:50.000000', NULL, 1),
(7560557, 1212092, 140305, '<td valign="top">One down, one to go, hope that rock is stable! Nice pick for this challenge.</td>', 'One down, one to go, hope that rock is stable! Nice pick for this challenge.', '2018-02-23 12:26:37.000000', NULL, 1),
(7560580, 1212002, 28742, '<td valign="top">It''s just guarding the pile. You know, like the old saying, "How much wood could a woodgourd guard if a woodgourd could guard wood?"</td>', 'It''s just guarding the pile. You know, like the old saying, "How much wood could a woodgourd guard if a woodgourd could guard wood?"', '2018-02-23 19:03:00.000000', NULL, 1),
(7560581, 1212172, 28742, '<td valign="top">I just need one stone... :P</td>', 'I just need one stone... :P', '2018-02-23 19:04:16.000000', NULL, 1),
(7560582, 1212158, 28742, '<td valign="top">Horrible. Just horrible. 9</td>', 'Horrible. Just horrible. 9', '2018-02-23 19:05:02.000000', NULL, 1),
(7560583, 1212156, 28742, '<td valign="top">Reminds me of the "Man hands" episode of Seinfeld.</td>', 'Reminds me of the "Man hands" episode of Seinfeld.', '2018-02-23 19:05:30.000000', NULL, 1),
(7560584, 1211783, 28742, '<td valign="top">Seems like they left that whitespace in the middle of the sign for you to write in your own expletive.</td>', 'Seems like they left that whitespace in the middle of the sign for you to write in your own expletive.', '2018-02-23 19:07:52.000000', NULL, 1),
(7560585, 1212003, 28742, '<td valign="top">Oof is an appropriate reaction to an image that is so badly in need of focus. :P</td>', 'Oof is an appropriate reaction to an image that is so badly in need of focus. :P', '2018-02-23 19:09:28.000000', NULL, 1),
(7560586, 1212159, 28742, '<td valign="top">Good: The thirsty cat is getting a much needed drink.<br/>Bad: Looks like there''s antifreeze in that water. :O<br/>:P</td>', 'Good: The thirsty cat is getting a much needed drink.Bad: Looks like there''s antifreeze in that water. :O:P', '2018-02-23 19:10:47.000000', NULL, 1),
(7560587, 1212177, 28742, '<td valign="top">20180221_134806, indeed!</td>', '20180221_134806, indeed!', '2018-02-23 19:13:02.000000', NULL, 1),
(7560588, 1212155, 28742, '<td valign="top">This is pretty good. But I won''t penalize you for that.</td>', 'This is pretty good. But I won''t penalize you for that.', '2018-02-23 19:14:36.000000', NULL, 1),
(7560589, 1212178, 28742, '<td valign="top">I''m conflicted as to whether this is so bad it''s good, or so good it''s DNMC. I''ll give you the benefit of my indecision. 7</td>', 'I''m conflicted as to whether this is so bad it''s good, or so good it''s DNMC. I''ll give you the benefit of my indecision. 7', '2018-02-23 19:16:48.000000', NULL, 1),
(7560590, 1212136, 28742, '<td valign="top">Awe, I like it, but I do believe that border is gonna get you a DQ. :(</td>', 'Awe, I like it, but I do believe that border is gonna get you a DQ. :(', '2018-02-23 19:18:11.000000', NULL, 1),
(7560592, 1211932, 28742, '<td valign="top">Interesting to see how this was without editing - camera mode? Photo of a photo? I''ll give you the benefit of the doubt. Anyway, it''s almost too good to be so bad it''s good. Good luck, though. :)</td>', 'Interesting to see how this was without editing - camera mode? Photo of a photo? I''ll give you the benefit of the doubt. Anyway, it''s almost too good to be so bad it''s good. Good luck, though. :)', '2018-02-23 19:24:24.000000', NULL, 1),
(7560607, 1212150, 97225, '<td valign="top">No bad about that at all!</td>', 'No bad about that at all!', '2018-02-23 20:46:15.000000', NULL, 1),
(7560610, 1212158, 97225, '<td valign="top">This actually meets the challenge. A ribbon from me.</td>', 'This actually meets the challenge. A ribbon from me.', '2018-02-23 20:51:35.000000', NULL, 1),
(7560645, 1212169, 101668, '<td valign="top">This in minimal, great job!</td>', 'This in minimal, great job!', '2018-02-24 08:13:11.000000', NULL, 1),
(7560669, 1212162, 65234, '<td valign="top">If you hasn''t mentioned the dog I would have missed it entirely. Which is bad. So congrats on that, or something.</td>', 'If you hasn''t mentioned the dog I would have missed it entirely. Which is bad. So congrats on that, or something.', '2018-02-24 11:01:09.000000', NULL, 1),
(7560670, 1212092, 65234, '<td valign="top">Snapshot, you can''t see their faces, and you cut someone in half. Oh, and you blew the highlights in the water. Still, it''s all in focus, so not as bad as it could be.</td>', 'Snapshot, you can''t see their faces, and you cut someone in half. Oh, and you blew the highlights in the water. Still, it''s all in focus, so not as bad as it could be.', '2018-02-24 11:02:47.000000', NULL, 1),
(7560671, 1212150, 65234, '<td valign="top">Even with only one subject facing the camera and the focus looking sharpest on a couple of behinds, this one isn''t looking that awful to me. Could have more contrast, I suppose, but with the snow I don''t mind the haziness. Not bad enough for my taste (I can''t believe I''m looking for true badness!).</td>', 'Even with only one subject facing the camera and the focus looking sharpest on a couple of behinds, this one isn''t looking that awful to me. Could have more contrast, I suppose, but with the snow I don''t mind the haziness. Not bad enough for my taste (I can''t believe I''m looking for true badness!).', '2018-02-24 11:09:24.000000', NULL, 1),
(7560672, 1211995, 170281, '<td valign="top">Definitely made me laugh.  Great creativity and lighting.</td>', 'Definitely made me laugh.  Great creativity and lighting.', '2018-02-24 11:09:40.000000', NULL, 1),
(7560673, 1212173, 65234, '<td valign="top">This one is ... well, I have no idea what it really is. Which could be bad or good, but for this challenge we''ll go with bad.</td>', 'This one is ... well, I have no idea what it really is. Which could be bad or good, but for this challenge we''ll go with bad.', '2018-02-24 11:10:54.000000', NULL, 1),
(7560675, 1212167, 65234, '<td valign="top">Yeah, I wouldn''t normally have so much out of focus in the foreground unless that enhanced the image, and I''m torn on whether this adds enough of a pattern and leading lines to be interesting. Not a huge fan of centered compositions, so you have that going for you on the badness scale.</td>', 'Yeah, I wouldn''t normally have so much out of focus in the foreground unless that enhanced the image, and I''m torn on whether this adds enough of a pattern and leading lines to be interesting. Not a huge fan of centered compositions, so you have that going for you on the badness scale.', '2018-02-24 11:17:14.000000', NULL, 1),
(7560676, 1212169, 65234, '<td valign="top">You got great detail inside the bird''s mouth, which I find interesting, and therefore don''t deem this a bad image. I mean, the eyes are in focus, too. Just not bad enough to rise near the top of my ranking.</td>', 'You got great detail inside the bird''s mouth, which I find interesting, and therefore don''t deem this a bad image. I mean, the eyes are in focus, too. Just not bad enough to rise near the top of my ranking.', '2018-02-24 11:19:18.000000', NULL, 1),
(7560677, 1212171, 65234, '<td valign="top">Just, ewww. So that''s a big badness. The composition isn''t bad and I don''t mind the DOF, so overall middling badness here.</td>', 'Just, ewww. So that''s a big badness. The composition isn''t bad and I don''t mind the DOF, so overall middling badness here.', '2018-02-24 11:20:52.000000', NULL, 1),
(7560679, 1211995, 65234, '<td valign="top">Another eww! But you made me laugh, so you lose a badness point for amusing me. No, wait, you *gain* a point for being so bad you did something good ... I think.</td>', 'Another eww! But you made me laugh, so you lose a badness point for amusing me. No, wait, you *gain* a point for being so bad you did something good ... I think.', '2018-02-24 11:23:04.000000', NULL, 1),
(7560680, 1212034, 65234, '<td valign="top">That''s rather uninteresting and the bird (cormorant?) isn''t in focus, so ... badly done. Congrats.</td>', 'That''s rather uninteresting and the bird (cormorant?) isn''t in focus, so ... badly done. Congrats.', '2018-02-24 11:24:08.000000', NULL, 1),
(7560681, 1212153, 65234, '<td valign="top">Ordinary but well photographed, so not bad IMO. You just skipped straight to good.</td>', 'Ordinary but well photographed, so not bad IMO. You just skipped straight to good.', '2018-02-24 11:25:22.000000', NULL, 1),
(7560684, 1211932, 65234, '<td valign="top">It''s cluttered and underexposed in some places and overexposed in others. Also at a slight tilt, which is the kind I never like since I can''t tell if the tilt is intentional or not. But it is telling a story of a city in the rain, so the clutter and harshness make sense to me, and the tilt could be indicative of the confusion of a tourist. Which is not so bad.</td>', 'It''s cluttered and underexposed in some places and overexposed in others. Also at a slight tilt, which is the kind I never like since I can''t tell if the tilt is intentional or not. But it is telling a story of a city in the rain, so the clutter and harshness make sense to me, and the tilt could be indicative of the confusion of a tourist. Which is not so bad.', '2018-02-24 11:31:26.000000', NULL, 1),
(7560686, 1212172, 65234, '<td valign="top">Composition isn''t doing anything for me, but the birds seem to be in focus and the inclusion of the chains adds interest. Not terribly bad.</td>', 'Composition isn''t doing anything for me, but the birds seem to be in focus and the inclusion of the chains adds interest. Not terribly bad.', '2018-02-24 11:36:07.000000', NULL, 1),
(7560687, 1212177, 65234, '<td valign="top">Another one that made me giggle. How many times has the camera autofocussed on the less interesting thing? That''s assuming the flowers/leaves are more interesting than the traffic. So we''ll give you the bad and add a bonus point for amusement.</td>', 'Another one that made me giggle. How many times has the camera autofocussed on the less interesting thing? That''s assuming the flowers/leaves are more interesting than the traffic. So we''ll give you the bad and add a bonus point for amusement.', '2018-02-24 11:38:15.000000', NULL, 1),
(7560688, 1212164, 65234, '<td valign="top">I don''t know; I kind of like the shadows of the people on high. And the little people below. Not horrible.</td>', 'I don''t know; I kind of like the shadows of the people on high. And the little people below. Not horrible.', '2018-02-24 11:39:59.000000', NULL, 1),
(7560689, 1212166, 65234, '<td valign="top">The result here is an interesting abstract. Which is good (I especially love that yin/yang object on the upper left). So I guess my interpretation of the image''s badness, and there has to be some for this challenge, depends on what would have been a "good" capture of the scene. And I have no way of knowing that. So let''s assume a middling degree of badness that made it to good. (BTW, my head hurts from trying to figure out how to vote on this!).</td>', 'The result here is an interesting abstract. Which is good (I especially love that yin/yang object on the upper left). So I guess my interpretation of the image''s badness, and there has to be some for this challenge, depends on what would have been a "good" capture of the scene. And I have no way of knowing that. So let''s assume a middling degree of badness that made it to good. (BTW, my head hurts from trying to figure out how to vote on this!).', '2018-02-24 11:47:42.000000', NULL, 1),
(7560690, 1212155, 65234, '<td valign="top">That''s unattractive. Reasonably composed and the DOF is nice, so not truly awful.</td>', 'That''s unattractive. Reasonably composed and the DOF is nice, so not truly awful.', '2018-02-24 11:48:57.000000', NULL, 1),
(7560693, 1211640, 65234, '<td valign="top">See, I kind of like images like this, where the motion of the camera and the light (did you use a flash?) make interesting patterns. So ... bad but not horrid, and definitely trending to good to my eye.</td>', 'See, I kind of like images like this, where the motion of the camera and the light (did you use a flash?) make interesting patterns. So ... bad but not horrid, and definitely trending to good to my eye.', '2018-02-24 11:50:56.000000', NULL, 1),
(7560695, 1212136, 65234, '<td valign="top">This makes my eyes hurt trying to focus. Which is decidedly bad; so congrats on that. The image has a ghostly feel to it, which I''m rating as a good thing.</td>', 'This makes my eyes hurt trying to focus. Which is decidedly bad; so congrats on that. The image has a ghostly feel to it, which I''m rating as a good thing.', '2018-02-24 11:52:53.000000', NULL, 1),
(7560696, 1212178, 65234, '<td valign="top">The focus on the reflection of the trees is actually quite nice. Oddly cropped with just bits of the right-side-up world showing, so I''ll count that as a bit of badness. But I don''t think the badness makes it good, if that makes sense.</td>', 'The focus on the reflection of the trees is actually quite nice. Oddly cropped with just bits of the right-side-up world showing, so I''ll count that as a bit of badness. But I don''t think the badness makes it good, if that makes sense.', '2018-02-24 11:54:35.000000', NULL, 1),
(7560697, 1212180, 65234, '<td valign="top">Everyone is on FB. It''s the Borg.<br/> <br/>The image ... hard to see through the window and the background is overexposed, so congrats on that. Not sure the badness makes it good, though.</td>', 'Everyone is on FB. It''s the Borg. The image ... hard to see through the window and the background is overexposed, so congrats on that. Not sure the badness makes it good, though.', '2018-02-24 11:57:39.000000', NULL, 1),
(7560698, 1211815, 65234, '<td valign="top">Not bad at all. The shadowy figure in the shower is sufficiently mysterious for interest. Maybe could have been cropped tighter to get rid of some things distracting me, but that''s only a little bad.</td>', 'Not bad at all. The shadowy figure in the shower is sufficiently mysterious for interest. Maybe could have been cropped tighter to get rid of some things distracting me, but that''s only a little bad.', '2018-02-24 11:59:21.000000', NULL, 1),
(7560699, 1212156, 65234, '<td valign="top">That distortion is really quite atrocious. And is she going to eat the purse and shopping bag? ''Cuz that''s just weird. But I''m busily trying to figure out what she IS eating, and am curious about what she''s looking at, so there are some good things about the image. And the distortion certainly draws the eye, which is ... good?</td>', 'That distortion is really quite atrocious. And is she going to eat the purse and shopping bag? ''Cuz that''s just weird. But I''m busily trying to figure out what she IS eating, and am curious about what she''s looking at, so there are some good things about the image. And the distortion certainly draws the eye, which is ... good?', '2018-02-24 12:02:22.000000', NULL, 1),
(7560701, 1212070, 65234, '<td valign="top">Something is sucking the souls out of those horses =:-O  So that weird bit of motion blur actually interests me. Which is good.</td>', 'Something is sucking the souls out of those horses =:-O  So that weird bit of motion blur actually interests me. Which is good.', '2018-02-24 12:04:36.000000', NULL, 1),
(7560702, 1212158, 65234, '<td valign="top">Looks kind of like an abstract flower with a bug nearby. Or, you know, fishing. Not sure what it actually is, but the motion blur gives me no real glimpse of the subject, or I''m just not seeing it, so I''ll count that as a bad thing. It''s not really a bad image, though; I rather like it.</td>', 'Looks kind of like an abstract flower with a bug nearby. Or, you know, fishing. Not sure what it actually is, but the motion blur gives me no real glimpse of the subject, or I''m just not seeing it, so I''ll count that as a bad thing. It''s not really a bad image, though; I rather like it.', '2018-02-24 12:08:05.000000', NULL, 1),
(7560704, 1211847, 65234, '<td valign="top">My eyes hurt from trying to find something that IS in focus. So many things in this image. I think if it were even more unfocussed and rotated 90 degrees left it would make a way cool pattern, which would be the result of the out-of-focusness and therefore just right for this challenge.</td>', 'My eyes hurt from trying to find something that IS in focus. So many things in this image. I think if it were even more unfocussed and rotated 90 degrees left it would make a way cool pattern, which would be the result of the out-of-focusness and therefore just right for this challenge.', '2018-02-24 12:12:43.000000', NULL, 1),
(7560705, 1212159, 65234, '<td valign="top">Well, the focus is slightly off, but it''s otherwise a perfectly fine image.</td>', 'Well, the focus is slightly off, but it''s otherwise a perfectly fine image.', '2018-02-24 12:15:36.000000', NULL, 1),
(7560706, 1212090, 65234, '<td valign="top">This is a strange image but not a bad one, really..</td>', 'This is a strange image but not a bad one, really..', '2018-02-24 12:16:32.000000', NULL, 1),
(7560707, 1211968, 65234, '<td valign="top">The light showers make some interesting leading lines. So the weirdness of the light streaks actually adds interest, which is good.</td>', 'The light showers make some interesting leading lines. So the weirdness of the light streaks actually adds interest, which is good.', '2018-02-24 12:18:33.000000', NULL, 1),
(7560708, 1211783, 65234, '<td valign="top">I am having trouble finding anything specifically wrong with this. It''s just uninteresting  to me and slightly crooked, though that could have been to accommodate the construction crane. But nothing that I don''t like about it rises to the level of goodness because of its badness.</td>', 'I am having trouble finding anything specifically wrong with this. It''s just uninteresting  to me and slightly crooked, though that could have been to accommodate the construction crane. But nothing that I don''t like about it rises to the level of goodness because of its badness.', '2018-02-24 12:24:58.000000', NULL, 1),
(7560709, 1212002, 65234, '<td valign="top">I find this kind of interesting, and it''s in focus. Not bad enough in my estimation.</td>', 'I find this kind of interesting, and it''s in focus. Not bad enough in my estimation.', '2018-02-24 12:25:36.000000', NULL, 1),
(7560710, 1211929, 65234, '<td valign="top">Well, I can''t really see the house, so congrats on making your subject impossible to see. And I rather like the bokeh, so what''s bad about an image of a house is actually good for a more abstract appreciation of the image.</td>', 'Well, I can''t really see the house, so congrats on making your subject impossible to see. And I rather like the bokeh, so what''s bad about an image of a house is actually good for a more abstract appreciation of the image.', '2018-02-24 12:28:30.000000', NULL, 1),
(7560711, 1212157, 65234, '<td valign="top">Toddlers certainly keep ME off-kilter so this image makes perfect sense to me LOL.</td>', 'Toddlers certainly keep ME off-kilter so this image makes perfect sense to me LOL.', '2018-02-24 12:29:33.000000', NULL, 1),
(7560712, 1212179, 65234, '<td valign="top">This is making me dizzy! Love the pattern on the stairs, so I''m going to say the badness is good here.</td>', 'This is making me dizzy! Love the pattern on the stairs, so I''m going to say the badness is good here.', '2018-02-24 12:29:40.000000', NULL, 1),
(7560713, 1212170, 65234, '<td valign="top">This is truly an assault on my eyes. The addition of the glass on the upper right seems totally random, and the little drop flowers and the big flowers have my eyes darting all over the place. It''s not a restful image LOL. But you made me laugh. Don''t know if that was your intent but it gets the image into "so bad it''s good" territory nicely.</td>', 'This is truly an assault on my eyes. The addition of the glass on the upper right seems totally random, and the little drop flowers and the big flowers have my eyes darting all over the place. It''s not a restful image LOL. But you made me laugh. Don''t know if that was your intent but it gets the image into "so bad it''s good" territory nicely.', '2018-02-24 12:29:48.000000', NULL, 1),
(7560726, 1211995, 42733, '<td valign="top">My favorite in this challenge.</td>', 'My favorite in this challenge.', '2018-02-24 17:37:43.000000', NULL, 1),
(7560727, 1212170, 42733, '<td valign="top">In my top 3.</td>', 'In my top 3.', '2018-02-24 17:38:03.000000', NULL, 1),
(7560728, 1212092, 42733, '<td valign="top">In my top 3.</td>', 'In my top 3.', '2018-02-24 17:38:16.000000', NULL, 1),
(7560735, 1212159, 97225, '<td valign="top">Lovely photo. I can''t give you a good score because I can''t see much that''s bad about it.</td>', 'Lovely photo. I can''t give you a good score because I can''t see much that''s bad about it.', '2018-02-24 18:18:33.000000', NULL, 1),
(7560736, 1212092, 97225, '<td valign="top">I can''t identify the ''so bad'' aspect of this. The half-guy on the right is a mere flaw, forgivable in a minimal challenge.</td>', 'I can''t identify the ''so bad'' aspect of this. The half-guy on the right is a mere flaw, forgivable in a minimal challenge.', '2018-02-24 18:29:11.000000', NULL, 1),
(7560738, 1212169, 97225, '<td valign="top">Interesting, well composed, nice shallow dof focus where it should be, high-key rather than overexposed - if I took this shot I''d be pleased with it. It doesn''t say ''so bad'' to me at all.</td>', 'Interesting, well composed, nice shallow dof focus where it should be, high-key rather than overexposed - if I took this shot I''d be pleased with it. It doesn''t say ''so bad'' to me at all.', '2018-02-24 18:35:51.000000', NULL, 1),
(7560740, 1211968, 63218, '<td valign="top">I don''t care what anyone says--I like this a lot. An ordinary scene transformed by the photographer to the extraordinary. I love it that at first glance it looks like a downtown meteor shower, yet the people are so calm it makes this extraordinary event quite ... normal everyday. Not sure what in the world it has to do with this strange challenge, but I don''t care.  10</td>', 'I don''t care what anyone says--I like this a lot. An ordinary scene transformed by the photographer to the extraordinary. I love it that at first glance it looks like a downtown meteor shower, yet the people are so calm it makes this extraordinary event quite ... normal everyday. Not sure what in the world it has to do with this strange challenge, but I don''t care.  10', '2018-02-24 19:59:50.000000', NULL, 1),
(7560742, 1211995, 63218, '<td valign="top">Yes I did, I LOLd!</td>', 'Yes I did, I LOLd!', '2018-02-24 20:03:45.000000', NULL, 1),
(7560752, 1212158, 182284, '<td valign="top">Nice color play.</td>', 'Nice color play.', '2018-02-24 22:06:23.000000', NULL, 1),
(7560753, 1212164, 182284, '<td valign="top">I''m confused.</td>', 'I''m confused.', '2018-02-24 22:06:50.000000', NULL, 1),
(7560754, 1211995, 182284, '<td valign="top">Seriously? This really does fit the challenge.</td>', 'Seriously? This really does fit the challenge.', '2018-02-24 22:07:57.000000', NULL, 1),
(7560755, 1212173, 182284, '<td valign="top">Oh my time to call Doctor Who.</td>', 'Oh my time to call Doctor Who.', '2018-02-24 22:08:26.000000', NULL, 1),
(7560756, 1212177, 182284, '<td valign="top">Fits the challenge perfectly.</td>', 'Fits the challenge perfectly.', '2018-02-24 22:08:50.000000', NULL, 1),
(7560757, 1211783, 182284, '<td valign="top">Hum...wires everywhere. Fits the challenge.</td>', 'Hum...wires everywhere. Fits the challenge.', '2018-02-24 22:09:34.000000', NULL, 1),
(7560758, 1212034, 182284, '<td valign="top">Oh my gosh, at first it looked as if the bird was walking on one long foot. LOL</td>', 'Oh my gosh, at first it looked as if the bird was walking on one long foot. LOL', '2018-02-24 22:10:38.000000', NULL, 1),
(7560759, 1212092, 182284, '<td valign="top">Rough going with little ones.</td>', 'Rough going with little ones.', '2018-02-24 22:12:03.000000', NULL, 1),
(7560760, 1212178, 182284, '<td valign="top">Wow, if this is minimal it''s amazing. I would like to know how you captured it.</td>', 'Wow, if this is minimal it''s amazing. I would like to know how you captured it.', '2018-02-24 22:14:17.000000', NULL, 1),
